def is_beyond(a: ImagePatch, b: ImagePatch, direction: str) -> bool:
    if direction == 'left':
        return a.right < b.left
    elif direction == 'right':
        return a.left > b.right
    elif direction == 'above':
        return a.lower < b.upper
